/**
 * WORKER A: Management Panel & Administration Layer (ZEUS)
 * 
 * Strict Role: Administration & Display ONLY.
 * - Login, initial setup, session management (cryptographically random session tokens).
 * - Login rate limiting / brute-force protection.
 * - Dynamic configuration with authoritative runtime endpoints (Worker B/C/D).
 * - Full HTML/JS escaping to prevent XSS.
 * - Tokenized, revocable subscription display (generated by Worker D).
 * - Tokenized user status cards (no username enumeration).
 * - Authenticated diagnostics testing internal health of Worker B, C, D.
 * - Persian RTL interface with rich dashboard, worker status monitor, user management.
 * 
 * Strict Boundaries:
 * - NO VLESS / Trojan / Shadowsocks protocol parsing.
 * - NO WebSocket proxying or raw connection forwarding.
 * - NO TCP socket dialing (connect()).
 * - NO direct D1 access (delegated to Worker B).
 * - NO direct GitHub / external repo fetches (delegated to Worker C).
 * - NO exposure of INTERNAL_AUTH_TOKEN to browser JavaScript or JSON responses.
 */

// In-memory rate limiting map for login attempts: ip -> { count, lastAttempt }
const LOGIN_ATTEMPTS = new Map();
const MAX_LOGIN_ATTEMPTS = 5;
const LOCKOUT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

function safeJson(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store"
    }
  });
}

// Comprehensive HTML escaping helper to prevent XSS injection
function escapeHtml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function normalizeUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== "string") return "";
  const trimmed = rawUrl.trim();
  try {
    const parsed = new URL(trimmed);
    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return "";
    return `${parsed.protocol}//${parsed.host}${parsed.pathname.replace(/\/+$/, "")}`;
  } catch (_) {
    return "";
  }
}

// Authoritative configuration loader: Reads bootstrap env, then overrides with Worker B persistent settings
async function getEffectiveConfig(env) {
  let dbUrl = normalizeUrl(env.DB_SERVICE_URL);
  let cacheUrl = normalizeUrl(env.CACHE_SERVICE_URL);
  let proxyUrl = normalizeUrl(env.PROXY_SERVICE_URL);
  let secretGate = (env.SECRET_ROUTE_GATE || "").trim();

  // Load authoritative dynamic configuration from Worker B
  try {
    const res = await callWorkerB("/api/internal/settings", "GET", null, env, dbUrl);
    if (res && res.success && res.settings) {
      if (res.settings.db_service_url) {
        const dynDb = normalizeUrl(res.settings.db_service_url);
        if (dynDb) dbUrl = dynDb;
      }
      if (res.settings.cache_service_url) {
        const dynCache = normalizeUrl(res.settings.cache_service_url);
        if (dynCache) cacheUrl = dynCache;
      }
      if (res.settings.proxy_service_url) {
        const dynProxy = normalizeUrl(res.settings.proxy_service_url);
        if (dynProxy) proxyUrl = dynProxy;
      }
      if (res.settings.secret_route_gate !== undefined) {
        secretGate = String(res.settings.secret_route_gate).trim();
      }
    }
  } catch (_) {}

  return { dbUrl, cacheUrl, proxyUrl, secretGate };
}

// Inter-Worker RPC Clients using Authoritative URLs
async function callWorkerB(path, method = "GET", body = null, env = {}, authoritativeUrl = null) {
  const token = env.INTERNAL_AUTH_TOKEN || "";
  if (env.DB_SERVICE && typeof env.DB_SERVICE.fetch === "function") {
    const req = new Request(`https://internal-db${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    const res = await env.DB_SERVICE.fetch(req);
    return await res.json().catch(() => ({}));
  }

  const baseUrl = authoritativeUrl || normalizeUrl(env.DB_SERVICE_URL);
  if (!baseUrl) return { success: false, error: "Database service URL is not configured." };

  try {
    const res = await fetch(`${baseUrl}${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    return await res.json().catch(() => ({}));
  } catch (err) {
    return { success: false, error: "Worker B unreachable: " + err.message };
  }
}

async function callWorkerC(path, method = "GET", body = null, env = {}, authoritativeUrl = null) {
  const token = env.INTERNAL_AUTH_TOKEN || "";
  if (env.CACHE_SERVICE && typeof env.CACHE_SERVICE.fetch === "function") {
    const req = new Request(`https://internal-cache${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    const res = await env.CACHE_SERVICE.fetch(req);
    return await res.json().catch(() => ({}));
  }

  const baseUrl = authoritativeUrl || normalizeUrl(env.CACHE_SERVICE_URL);
  if (!baseUrl) return { success: false, error: "Cache service URL is not configured." };

  try {
    const res = await fetch(`${baseUrl}${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    return await res.json().catch(() => ({}));
  } catch (err) {
    return { success: false, error: "Worker C unreachable: " + err.message };
  }
}

async function callWorkerD(path, method = "GET", body = null, env = {}, authoritativeUrl = null) {
  const token = env.INTERNAL_AUTH_TOKEN || "";
  if (env.PROXY_SERVICE && typeof env.PROXY_SERVICE.fetch === "function") {
    const req = new Request(`https://internal-proxy${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    const res = await env.PROXY_SERVICE.fetch(req);
    return await res.json().catch(() => ({}));
  }

  const baseUrl = authoritativeUrl || normalizeUrl(env.PROXY_SERVICE_URL);
  if (!baseUrl) return { success: false, error: "Connection/Proxy service URL is not configured." };

  try {
    const res = await fetch(`${baseUrl}${path}`, {
      method,
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
        "X-Internal-Token": token
      },
      body: body ? JSON.stringify(body) : undefined
    });
    return await res.json().catch(() => ({}));
  } catch (err) {
    return { success: false, error: "Worker D unreachable: " + err.message };
  }
}

// Secret Route Gate Validation
function checkSecretRouteGate(url, request, secretGate) {
  if (!secretGate) return { passed: true, cleanPath: url.pathname };

  const queryGate = url.searchParams.get("gate");
  if (queryGate === secretGate) {
    return { passed: true, cleanPath: url.pathname, setGateCookie: true };
  }

  const prefix = `/${secretGate}`;
  if (url.pathname === prefix || url.pathname.startsWith(`${prefix}/`)) {
    const cleanPath = url.pathname.slice(prefix.length) || "/";
    return { passed: true, cleanPath, setGateCookie: true };
  }

  const cookies = request.headers.get("Cookie") || "";
  if (cookies.includes(`panel_gate=${secretGate}`)) {
    return { passed: true, cleanPath: url.pathname };
  }

  // Public asset and tokenized user status paths
  if (
    url.pathname.startsWith("/status/") ||
    url.pathname === "/icon.svg" ||
    url.pathname === "/favicon.ico"
  ) {
    return { passed: true, cleanPath: url.pathname };
  }

  return { passed: false };
}

// Session Validation using Cryptographically Random Tokens (delegated to Worker B)
async function verifySessionAuth(request, env, authoritativeDbUrl) {
  const cookies = request.headers.get("Cookie") || "";
  const match = cookies.split(";").find(c => c.trim().startsWith("panel_session="));
  if (!match) return false;
  const sessionToken = match.split("=")[1].trim();

  const res = await callWorkerB("/api/internal/auth/verify-session", "POST", { sessionToken }, env, authoritativeDbUrl);
  return Boolean(res && res.valid);
}

// Login Rate Limiting (Brute-Force Protection)
function checkLoginRateLimit(clientIp) {
  const now = Date.now();
  const record = LOGIN_ATTEMPTS.get(clientIp);

  if (record) {
    if (now - record.lastAttempt > LOCKOUT_WINDOW_MS) {
      LOGIN_ATTEMPTS.delete(clientIp);
      return { allowed: true };
    }
    if (record.count >= MAX_LOGIN_ATTEMPTS) {
      const remainingMinutes = Math.ceil((LOCKOUT_WINDOW_MS - (now - record.lastAttempt)) / 60000);
      return {
        allowed: false,
        error: `به دلیل تلاش‌های ناموفق مکرر، دسترسی شما موقتاً مسدود شد. لطفاً ${remainingMinutes} دقیقه دیگر تلاش کنید.`
      };
    }
  }

  return { allowed: true };
}

function recordFailedLogin(clientIp) {
  const now = Date.now();
  const record = LOGIN_ATTEMPTS.get(clientIp) || { count: 0, lastAttempt: now };
  record.count += 1;
  record.lastAttempt = now;
  LOGIN_ATTEMPTS.set(clientIp, record);
}

function recordSuccessfulLogin(clientIp) {
  LOGIN_ATTEMPTS.delete(clientIp);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 1. Health Endpoint
    if (url.pathname === "/health") {
      return safeJson({
        status: "healthy",
        service: "worker-a-panel",
        timestamp: Date.now()
      });
    }

    // Load authoritative runtime configuration from Worker B
    const config = await getEffectiveConfig(env);

    // 2. Secret Route Gate
    const gateCheck = checkSecretRouteGate(url, request, config.secretGate);
    if (!gateCheck.passed) {
      return new Response("Nothing to see here", {
        status: 404,
        headers: { "Content-Type": "text/plain; charset=utf-8" }
      });
    }

    const currentPath = gateCheck.cleanPath;

    // 3. Static Assets
    if (currentPath === "/icon.svg" || currentPath === "/favicon.ico") {
      return new Response(SVG_ICON, {
        headers: { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "public, max-age=604800" }
      });
    }

    // 4. Secure User Status Display (/status/<status_token>)
    if (currentPath.startsWith("/status/")) {
      return await handleStatusRoute(request, currentPath, config, env);
    }

    // 5. Admin API Routes
    if (currentPath.startsWith("/api/")) {
      return await handleAdminApi(request, currentPath, config, env, ctx);
    }

    // 6. Panel / Login / Setup HTML Views
    if (currentPath === "/panel" || currentPath === "/login" || currentPath === "/setup" || currentPath === "/") {
      return await handlePanelHtml(request, currentPath, config, env, gateCheck);
    }

    return new Response("Not Found", { status: 404 });
  }
};

// --- HANDLERS ---

async function handleStatusRoute(request, pathname, config, env) {
  const token = decodeURIComponent(pathname.slice("/status/".length)).trim();
  if (!token) {
    return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
  }

  // Lookup user by status_token exclusively to prevent username enumeration
  const userRes = await callWorkerB(`/api/internal/user/${encodeURIComponent(token)}`, "GET", null, env, config.dbUrl);
  
  // If not found by status_token, check if requester has an authenticated admin session
  let user = null;
  if (userRes && userRes.user && userRes.user.status_token === token) {
    user = userRes.user;
  } else {
    // If not matching token, only allow username lookup if caller is authenticated admin
    const isAdmin = await verifySessionAuth(request, env, config.dbUrl);
    if (isAdmin && userRes && userRes.user) {
      user = userRes.user;
    }
  }

  if (!user) {
    return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" } });
  }

  // Worker D tokenized subscription URL
  const proxyBase = config.proxyUrl || "https://worker-d.example.com";
  const subscriptionUrl = `${proxyBase}/sub/${user.sub_token || ""}`;
  const yamlUrl = `${proxyBase}/yaml/${user.sub_token || ""}`;

  // Safe data injection with escaping
  const safeUserData = {
    username: escapeHtml(user.username),
    limit_gb: user.limit_gb,
    used_gb: user.used_gb,
    is_active: user.is_active,
    expiry_days: user.expiry_days,
    created_at: user.created_at,
    connection_type: user.connection_type || "vless"
  };

  const html = STATUS_HTML_TEMPLATE
    .replace("/* {{USER_DATA_PLACEHOLDER}} */", `window.statusUser = ${JSON.stringify(safeUserData)}; window.subscriptionUrl = ${JSON.stringify(subscriptionUrl)}; window.yamlUrl = ${JSON.stringify(yamlUrl)};`);

  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8" } });
}

async function handlePanelHtml(request, pathname, config, env, gateCheck) {
  const hasPwdRes = await callWorkerB("/api/internal/auth/has-password", "GET", null, env, config.dbUrl);
  const hasPassword = Boolean(hasPwdRes && hasPwdRes.hasPassword);

  if (!hasPassword) {
    return new Response(SETUP_HTML_TEMPLATE, { headers: { "Content-Type": "text/html; charset=utf-8" } });
  }

  const isAuthed = await verifySessionAuth(request, env, config.dbUrl);
  if (!isAuthed) {
    return new Response(LOGIN_HTML_TEMPLATE, { headers: { "Content-Type": "text/html; charset=utf-8" } });
  }

  const headers = new Headers({
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-store, no-cache, must-revalidate"
  });

  if (gateCheck.setGateCookie && config.secretGate) {
    headers.set("Set-Cookie", `panel_gate=${config.secretGate}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=86400`);
  }

  return new Response(PANEL_HTML_TEMPLATE, { headers });
}

async function handleAdminApi(request, pathname, config, env, ctx) {
  const clientIp = request.headers.get("CF-Connecting-IP") || "unknown";

  // Setup initial password endpoint
  if (pathname === "/api/setup-password" && request.method === "POST") {
    const body = await request.json().catch(() => ({}));
    const res = await callWorkerB("/api/internal/auth/set-password", "POST", { password: body.password }, env, config.dbUrl);
    if (res && res.success && res.sessionToken) {
      return new Response(JSON.stringify({ success: true }), {
        headers: {
          "Content-Type": "application/json",
          "Set-Cookie": `panel_session=${res.sessionToken}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`
        }
      });
    }
    return safeJson({ success: false, error: res.error || "خطا در تنظیم رمز" }, 400);
  }

  // Login endpoint with Brute-Force Rate Limiting
  if (pathname === "/api/login" && request.method === "POST") {
    const rateCheck = checkLoginRateLimit(clientIp);
    if (!rateCheck.allowed) {
      return safeJson({ success: false, error: rateCheck.error }, 429);
    }

    const body = await request.json().catch(() => ({}));
    const res = await callWorkerB("/api/internal/auth/verify-password", "POST", { password: body.password }, env, config.dbUrl);
    if (res && res.success && res.sessionToken) {
      recordSuccessfulLogin(clientIp);
      return new Response(JSON.stringify({ success: true }), {
        headers: {
          "Content-Type": "application/json",
          "Set-Cookie": `panel_session=${res.sessionToken}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`
        }
      });
    }

    recordFailedLogin(clientIp);
    return safeJson({ success: false, error: "رمز عبور اشتباه است." }, 401);
  }

  // Logout endpoint
  if (pathname === "/api/logout" && request.method === "POST") {
    const cookies = request.headers.get("Cookie") || "";
    const match = cookies.split(";").find(c => c.trim().startsWith("panel_session="));
    if (match) {
      const sessionToken = match.split("=")[1].trim();
      ctx.waitUntil(callWorkerB("/api/internal/auth/destroy-session", "POST", { sessionToken }, env, config.dbUrl));
    }
    return new Response(JSON.stringify({ success: true }), {
      headers: {
        "Content-Type": "application/json",
        "Set-Cookie": "panel_session=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; Secure; SameSite=Lax"
      }
    });
  }

  // Authenticate session for all subsequent admin endpoints
  const isAuthed = await verifySessionAuth(request, env, config.dbUrl);
  if (!isAuthed) {
    return safeJson({ success: false, error: "Unauthorized session." }, 401);
  }

  // Change Admin Password endpoint
  if (pathname === "/api/change-password" && request.method === "POST") {
    const body = await request.json().catch(() => ({}));
    const { oldPassword, newPassword } = body;
    if (!newPassword || newPassword.length < 4) {
      return safeJson({ success: false, error: "رمز عبور جدید باید حداقل ۴ نویسه باشد." }, 400);
    }

    // Verify old password
    const verifyRes = await callWorkerB("/api/internal/auth/verify-password", "POST", { password: oldPassword }, env, config.dbUrl);
    if (!verifyRes || !verifyRes.success) {
      return safeJson({ success: false, error: "رمز عبور فعلی اشتباه است." }, 400);
    }

    // Set new password
    const setRes = await callWorkerB("/api/internal/auth/set-password", "POST", { password: newPassword }, env, config.dbUrl);
    if (setRes && setRes.success && setRes.sessionToken) {
      return new Response(JSON.stringify({ success: true }), {
        headers: {
          "Content-Type": "application/json",
          "Set-Cookie": `panel_session=${setRes.sessionToken}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`
        }
      });
    }
    return safeJson({ success: false, error: setRes.error || "خطا در تغییر رمز عبور" }, 500);
  }

  // 1. Dynamic Endpoints & Diagnostics (NEVER returns INTERNAL_AUTH_TOKEN)
  if (pathname === "/api/settings/endpoints") {
    if (request.method === "GET") {
      return safeJson({
        success: true,
        db_service_url: config.dbUrl,
        cache_service_url: config.cacheUrl,
        proxy_service_url: config.proxyUrl,
        secret_route_gate: config.secretGate
      });
    }
    if (request.method === "POST") {
      const body = await request.json().catch(() => ({}));
      const newSettings = {};
      if (body.db_service_url !== undefined) newSettings.db_service_url = normalizeUrl(body.db_service_url);
      if (body.cache_service_url !== undefined) newSettings.cache_service_url = normalizeUrl(body.cache_service_url);
      if (body.proxy_service_url !== undefined) newSettings.proxy_service_url = normalizeUrl(body.proxy_service_url);
      if (body.secret_route_gate !== undefined) newSettings.secret_route_gate = String(body.secret_route_gate).trim();

      const saveRes = await callWorkerB("/api/internal/settings", "POST", { settings: newSettings }, env, config.dbUrl);
      return safeJson(saveRes);
    }
  }

  // Authenticated Diagnostics & Latency Test (Tests internal authenticated endpoints using effective URLs)
  if (pathname === "/api/settings/test-endpoints" && request.method === "POST") {
    const tests = {};

    // Worker B test (authenticated internal health using config.dbUrl)
    const t0 = Date.now();
    const bRes = await callWorkerB("/api/internal/health", "GET", null, env, config.dbUrl);
    tests.worker_b = {
      status: bRes.status === "healthy" && bRes.authenticated ? "healthy" : "error",
      ping: Date.now() - t0,
      service: bRes.service || "worker-b-db"
    };

    // Worker C test (authenticated internal health using config.cacheUrl)
    const t1 = Date.now();
    const cRes = await callWorkerC("/api/internal/health", "GET", null, env, config.cacheUrl);
    tests.worker_c = {
      status: cRes.status === "healthy" && cRes.authenticated ? "healthy" : "error",
      ping: Date.now() - t1,
      service: cRes.service || "worker-c-cache"
    };

    // Worker D test (authenticated internal health using config.proxyUrl)
    const t2 = Date.now();
    const dRes = await callWorkerD("/api/internal/health", "GET", null, env, config.proxyUrl);
    tests.worker_d = {
      status: dRes.status === "healthy" && dRes.authenticated ? "healthy" : "error",
      ping: Date.now() - t2,
      service: dRes.service || "worker-d-proxy"
    };

    return safeJson({ success: true, tests });
  }

  // 2. User Operations (Delegated to Worker B using config.dbUrl)
  if (pathname.startsWith("/api/users")) {
    const subPath = pathname.replace("/api/users", "/api/internal/users");
    const body = request.method !== "GET" ? await request.json().catch(() => ({})) : null;
    const res = await callWorkerB(subPath, request.method, body, env, config.dbUrl);

    // If listing users, enrich each user with Worker D's tokenized subscription & status URLs
    if (request.method === "GET" && res.users) {
      const url = new URL(request.url);
      const proxyBase = config.proxyUrl || "https://worker-d.example.com";
      res.users = res.users.map(u => ({
        ...u,
        subscription_url: `${proxyBase}/sub/${encodeURIComponent(u.sub_token || "")}`,
        yaml_url: `${proxyBase}/yaml/${encodeURIComponent(u.sub_token || "")}`,
        status_url: `${url.protocol}//${url.host}/status/${encodeURIComponent(u.status_token || "")}`
      }));
    }

    return safeJson(res);
  }

  // Rotate & Revoke User Subscription Tokens
  if (pathname.startsWith("/api/user/") && pathname.endsWith("/revoke-tokens") && request.method === "POST") {
    const usernamePart = pathname.slice("/api/user/".length, pathname.length - "/revoke-tokens".length);
    const subPath = `/api/internal/user/${encodeURIComponent(usernamePart)}/revoke-tokens`;
    const res = await callWorkerB(subPath, "POST", {}, env, config.dbUrl);
    return safeJson(res);
  }

  // 3. Proxy Testing (Delegated to Worker C using config.cacheUrl)
  if (pathname === "/api/test-proxy" && request.method === "POST") {
    const body = await request.json().catch(() => ({}));
    const res = await callWorkerC("/api/internal/cache/test-proxy", "POST", body, env, config.cacheUrl);
    return safeJson(res);
  }

  // 4. General Settings (Delegated to Worker B using config.dbUrl)
  if (pathname === "/api/settings/bulk") {
    if (request.method === "GET") {
      const res = await callWorkerB("/api/internal/settings", "GET", null, env, config.dbUrl);
      return safeJson(res.settings || {});
    }
    const body = await request.json().catch(() => ({}));
    const res = await callWorkerB("/api/internal/settings", "POST", body, env, config.dbUrl);
    return safeJson(res);
  }

  return safeJson({ success: false, error: "Endpoint not found in Panel API." }, 404);
}

